import {downloadBackup} from './workspace.js';
import {stages,resources} from './data.js';
import {historyEntries} from './history-data.js';
import {concepts,missions,mistakes} from './concepts-data.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,text)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const stageName=id=>stages.find(s=>s.id===id)?.title||id;
const pageIntro=(label,title,desc)=>`<div class="page-intro"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>`;
const orbitalArt=()=>`<svg class="orbital-art" viewBox="0 0 620 570" role="img" aria-label="An illustrated orbital diagram connecting geometry, vectors, and functions"><defs><radialGradient id="planet"><stop stop-color="#8db6b9"/><stop offset=".66" stop-color="#31596d"/><stop offset="1" stop-color="#162d42"/></radialGradient><pattern id="hero-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#a6c3ce12"/></pattern><linearGradient id="fade"><stop stop-color="#efbb68"/><stop offset="1" stop-color="#efbb6830"/></linearGradient></defs><rect width="620" height="570" fill="url(#hero-grid)"/><g fill="none" stroke="#7695aa30"><circle cx="318" cy="288" r="219"/><path d="M318 35V541M64 288H574"/><path d="M158 128L478 448M158 448L478 128"/></g><g transform="rotate(-28 318 288)"><ellipse cx="318" cy="288" rx="260" ry="119" fill="none" stroke="#a2c9cd45" stroke-width="1"/><ellipse cx="318" cy="288" rx="240" ry="155" fill="none" stroke="#efbb68" stroke-width="1.5" stroke-dasharray="2 7"/></g><circle cx="318" cy="288" r="97" fill="url(#planet)" stroke="#8cbfc570"/><g stroke="#a1c8cd38" fill="none"><ellipse cx="318" cy="288" rx="96" ry="33"/><ellipse cx="318" cy="288" rx="96" ry="65"/><ellipse cx="318" cy="288" rx="32" ry="96"/><ellipse cx="318" cy="288" rx="66" ry="96"/><path d="M221 288H415M318 191V385"/></g><path d="M318 288L495 154" stroke="url(#fade)" stroke-dasharray="4 5"/><g transform="translate(495 154) rotate(-28)"><rect x="-11" y="-8" width="22" height="16" rx="2" fill="#efbb68"/><path d="M-16-14h-35v28h35M16-14h35v28H16" fill="#28465c" stroke="#9dced5"/><path d="M-40-14v28M-28-14v28M28-14v28M40-14v28M-51 0h35M16 0h35" stroke="#9dced580"/></g><g fill="#bad0da" font-family="monospace" font-size="11"><text x="57" y="89">01 / GEOMETRY</text><text x="388" y="72">02 / RELATIONSHIPS</text><text x="407" y="455">03 / MOTION</text><text x="71" y="431">A QUESTION BECOMES A MODEL.</text></g><g stroke="#9dced550" fill="none"><path d="M57 101h117l40 58M390 83h124v42M406 440v-32l-28-30"/></g><text x="333" y="233" fill="#efbb68" font-family="Georgia,serif" font-size="23" font-style="italic">r</text><circle cx="318" cy="288" r="3" fill="#efbb68"/><text x="318" y="531" text-anchor="middle" fill="#839eae" font-size="9" font-family="monospace" letter-spacing="2">A SCHEMATIC OF POSSIBILITY · NOT TO SCALE</text></svg>`;
export function overview(state){const checked=Object.values(state.checks||{}).filter(Boolean).length;return `<section class="atlas-hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> THE MATHEMATICS FIELD ATLAS</div><h1>Understand the math.<br> <em>Build what<br> comes next.</em></h1><p>From the first fraction to the language of flight. Discover where the ideas came from, why they work, and how to make them your own.</p><div class="actions"><a href="#diagnostic" class="btn gold">Find my starting point <span>↗</span></a><a href="#path" class="hero-text-link">Explore the learning path →</a></div><div class="hero-footnote"><span>FOUNDATIONS → ENGINEERING</span><span>YOUR PACE. A CLEAR DIRECTION.</span></div></div><div class="hero-art">${orbitalArt()}</div></section><div class="atlas-index"><span><b>06</b> learning stages</span><span><b>${historyEntries.length}</b> historical turning points</span><span><b>${concepts.length}</b> ideas made clear</span><span><b>05</b> interactive labs</span></div><section class="section"><div class="section-head"><div><div class="eyebrow">BEGIN WITH A QUESTION</div><h2>Where do you want<br> to go today?</h2></div><p>A learning path for direction. An atlas for curiosity. A workbench for discovering what you can actually do.</p></div><div class="entry-grid"><a class="entry-card" href="#diagnostic"><span class="entry-symbol">?</span><span class="overline">FIND YOUR LEVEL</span><h3>What should I<br> work on first?</h3><p>Take a short or full check and get a topic-by-topic starting recommendation.</p><span class="entry-arrow">↗</span></a><a class="entry-card" href="#concepts"><span class="entry-symbol">⅔</span><span class="overline">UNDERSTAND AN IDEA</span><h3>What does this<br> actually mean?</h3><p>Fractions, equality, functions, and more—explained with examples and common traps.</p><span class="entry-arrow">↗</span></a><a class="entry-card" href="#history"><span class="entry-symbol">∞</span><span class="overline">FOLLOW THE STORY</span><h3>Why did people<br> invent this?</h3><p>Counting, surveying, trade, astronomy, uncertainty, and the tools they inspired.</p><span class="entry-arrow">↗</span></a><a class="entry-card" href="#missions"><span class="entry-symbol">↗</span><span class="overline">CONNECT TO ENGINEERING</span><h3>Where does it<br> become useful?</h3><p>Work through spacecraft, robotics, power, scale, and navigation examples.</p><span class="entry-arrow">↗</span></a></div></section><section class="section journey-strip"><div><div class="eyebrow">THE FOUNDATION IS THE WORK</div><h2>Small ideas.<br> Long reach.</h2><p>Keep the destination in view without rushing the prerequisites.</p></div><div class="journey-track">${stages.filter(s=>s.id!=='geometry').map(s=>`<a href="#path/${s.id}"><span>${s.n}</span><b>${s.title}</b><small>${s.tag}</small><i>↗</i></a>`).join('')}<p>Geometry runs alongside algebra. “Ready for precalculus” means ready to begin it; finishing precalculus prepares you for calculus.</p></div></section><section class="section split-feature"><div class="feature-visual"><div class="overline">A RELATIONSHIP YOU CAN TOUCH</div><div class="big-equation">E <span>=</span> P × t</div><div class="energy-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p>40 watts × 3 hours = 120 watt-hours</p></div><div class="feature-copy"><div class="eyebrow">GO BEYOND WATCHING</div><h2>Make a prediction.<br> Move a slider.<br> Explain the change.</h2><p>Explore energy, linear functions, scaling, vectors, and circular orbits. Each lab shows the mathematics and the assumptions underneath.</p><a href="#labs" class="btn primary">Enter the interactive labs ↗</a></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">KEEP THE RESOURCE STACK SIMPLE</div><h2>A book. A practice tool.<br> A place to think.</h2></div><a href="#library" class="text-link">Browse all ${resources.length} resources →</a></div><div class="recommended"><article class="start-card"><span class="number">01 / MAIN TEXT</span><h3>OpenStax</h3><p>Start with Prealgebra, which begins with whole numbers. Continue through the algebra books as your skills develop.</p>${link(resources.find(r=>r.id==='open-pre').url,'Read the free book')}</article><article class="start-card"><span class="number">02 / FEEDBACK</span><h3>Khan Academy</h3><p>Practise the same skill, check your work, and find gaps. Keep written reasoning beside you.</p>${link(resources.find(r=>r.id==='khan-arithmetic').url,'Open arithmetic practice')}</article><article class="start-card"><span class="number">03 / YOUR WORK</span><h3>Paper & reflection</h3><p>Explain a step. Make an estimate. Record an error and the idea that fixes it. Return later and see what stayed.</p><a href="#notebook">Open your notebook →</a></article></div></section><section class="section progress-banner"><div><span class="overline">YOUR CONTINUITY</span><h3>${checked?`${checked} self-check${checked===1?'':'s'} marked. Keep building.`:'Your progress starts with one honest attempt.'}</h3><p>Bookmarks, self-checks, notes, and diagnostic progress stay in this browser.</p></div><a class="btn" href="#notebook">My workspace →</a></section>`;}

export function historyPage(id){const selected=historyEntries.find(h=>h.id===id)||historyEntries[0];return `${pageIntro('THE STORY OF MATHEMATICS','People had problems.<br> <em>Mathematics grew.</em>','Long before engineering degrees, people needed to count, share, measure, predict, navigate, and justify a result. These stories make the symbols less arbitrary.')}<div class="history-intro"><span>MEASUREMENT</span><span>TRADE</span><span>ASTRONOMY</span><span>PROOF</span><span>MOTION</span><span>COMPUTATION</span></div><div class="history-layout"><nav class="timeline" aria-label="Mathematics history">${historyEntries.map((h,i)=>`<a href="#history/${h.id}" class="${h.id===selected.id?'selected':''}" ${h.id===selected.id?'aria-current="step"':''}><span class="timeline-dot"></span><small>${esc(h.date)}</small><b>${esc(h.title)}</b><span>${esc(h.region)}</span></a>`).join('')}</nav><article class="history-story"><div class="story-meta"><span>${esc(selected.era)}</span><span>${esc(selected.region)}</span></div><div class="history-date">${esc(selected.date)}</div><h2>${esc(selected.title)}</h2><div class="story-block"><div class="eyebrow">THE HUMAN PROBLEM</div><p>${esc(selected.problem)}</p></div><div class="story-block"><div class="eyebrow">THE IDEA THAT HELPED</div><p>${esc(selected.idea)}</p></div><div class="example"><span>TRY THE IDEA IN TODAY’S NOTATION</span><p>${esc(selected.example)}</p></div><div class="story-block"><div class="eyebrow">THE CONNECTION TO ENGINEERING</div><p>${esc(selected.engineering)}</p></div><details open class="historical-care"><summary>A more accurate history</summary><p>${esc(selected.nuance)}</p></details><div class="source-links">${selected.sources.map(s=>link(s.url,s.title)).join('')}</div><div class="actions">${historyEntries.indexOf(selected)<historyEntries.length-1?`<a class="btn primary" href="#history/${historyEntries[historyEntries.indexOf(selected)+1].id}">Next turning point →</a>`:'<a class="btn primary" href="#concepts">Explore the ideas themselves →</a>'}</div></article></div><p class="smallprint section">This is a selective, connected history—not a claim that one person or civilization invented all of mathematics. Dates can refer to surviving evidence rather than the first time an idea was used.</p>`;}

export function conceptsPage(stage){const shown=concepts.filter(c=>!stage||stage==='all'||c.stage===stage);return `${pageIntro('THE CONCEPT ATLAS','The idea behind<br> <em>the procedure.</em>','A formula becomes easier to remember when it answers a question you understand. Explore the meaning, work the example, and test the boundary of each idea.')}<div class="pill-row stage-tabs"><a class="${!stage||stage==='all'?'active':''}" href="#concepts">All ideas</a>${stages.map(s=>`<a class="${stage===s.id?'active':''}" href="#concepts/${s.id}">${s.title}</a>`).join('')}</div><div class="concept-grid">${shown.map((c,i)=>`<article class="concept-card" id="concept-${c.id}"><div class="concept-top"><span class="overline">${stageName(c.stage)}</span><span>${String(i+1).padStart(2,'0')}</span></div><h2>${esc(c.title)}</h2><p class="concept-question">${esc(c.question)}</p><p>${esc(c.intuition)}</p><details><summary>Understand it, use it, test it <span>+</span></summary><div class="concept-section"><h4>Why the idea matters</h4><p>${esc(c.why)}</p></div><div class="example"><span>A WORKED IDEA</span><p>${esc(c.example)}</p></div><div class="concept-section"><h4>A common trap</h4><p>${esc(c.trap)}</p></div><div class="concept-section"><h4>Its engineering future</h4><p>${esc(c.engineering)}</p></div><div class="try-this"><span class="overline">TRY EXPLAINING THIS</span><p>${esc(c.tryThis)}</p><a href="#notebook/${c.id}">Write a reflection →</a></div><div class="source-links">${link(c.source.url,c.source.title)}</div><a class="text-link" href="#practice/${c.stage}">Practise ${stageName(c.stage)} →</a></details></article>`).join('')}</div>`;}

export function missionsPage(id){const m=missions.find(m=>m.id===id)||missions[0];return `${pageIntro('AEROSPACE & ROBOTICS','This is what<br> <em>the math is for.</em>','Start with a small, understandable model. Name the quantities, keep the units, state the assumptions, and solve the actual question. These examples show the route from foundations to engineering.')}<div class="mission-selector">${missions.map((x,i)=>`<a href="#missions/${x.id}" class="${x.id===m.id?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${esc(x.title)}</a>`).join('')}</div><section class="mission-brief"><div class="mission-cover"><div class="eyebrow">${esc(m.level)}</div><div class="mission-orbit"><span></span><i></i><b>↗</b></div><div><span class="overline">THE TOOLKIT</span><p>${esc(m.math)}</p></div></div><article><div class="eyebrow">${esc(m.subtitle)}</div><h2>${esc(m.title)}</h2><p class="mission-story">${esc(m.story)}</p><div class="worked-block"><div class="overline">WORK THE MODEL</div><p>${esc(m.worked)}</p></div><h3>What this example assumes</h3><p>${esc(m.assumptions)}</p><h3>What comes next</h3><p>${esc(m.next)}</p><div class="source-links">${link(m.source.url,m.source.title)}</div><div class="actions"><a href="#labs" class="btn primary">Experiment in the labs ↗</a><a href="#notebook/${m.id}" class="text-link">Keep a note →</a></div></article></section>`;}

export function mistakesPage(){return `${pageIntro('THE MISTAKE LAB','An error can show you<br> <em>exactly what to learn.</em>','Look for the first step that stopped being true. Repair the reason, then attempt a new example. These common mistakes are useful clues—not labels about your ability.')}<div class="mistake-list">${mistakes.map((m,i)=>`<article class="mistake-card"><div class="mistake-heading"><span>${String(i+1).padStart(2,'0')}</span><div><small>${stageName(m.stage)}</small><h2>${esc(m.title)}</h2></div></div><div class="mistake-comparison"><div><span>THE MISSTEP</span><p>${esc(m.wrong)}</p></div><div><span>THE REPAIR</span><p>${esc(m.right)}</p></div></div><div class="mistake-reason"><p>${esc(m.reason)}</p><details><summary>How to check yourself</summary><p>${esc(m.check)}</p><a href="#practice/${m.stage}">Try this topic →</a></details></div></article>`).join('')}</div><section class="section note"><b>A useful error note has three parts.</b><p>The step you took, why it was invalid, and a new example you can solve correctly. <a href="#notebook">Keep your own error notes in the workspace.</a></p></section>`;}

export const glossary=[
 ['Quantity','Something that can be counted or measured.','A mass of 4 kg is a quantity; both the number and the unit matter.','foundations'],['Variable','A symbol representing a quantity whose value may be unknown or may change.','In d = vt, d, v, and t represent distance, speed, and time.','algebra'],['Expression','A mathematical phrase that represents a value.','3x + 2 is an expression. It is not an equation by itself.','algebra'],['Equation','A statement that two expressions have the same value.','3x + 2 = 11 says the expressions on both sides are equal.','algebra'],['Equality (=)','The relation “has the same value as.”','The equals sign is not an instruction to start calculating.','foundations'],['Coefficient','A factor multiplying a variable or another expression.','In 5x, the coefficient of x is 5.','algebra'],['Term','A part of a sum, including its sign.','In 3x − 2, the terms are 3x and −2.','algebra'],['Factor','One of the quantities multiplied to form a product.','In (x − 2)(x + 3), each parenthesis is a factor.','algebra'],['Fraction','A quotient; it can also describe a share, a ratio, a number, or a scaling operation.','3/4 means 3 divided by 4. Three quarters of 20 is 15.','foundations'],['Ratio','A comparison by division.','A 2:3 ratio compares two amounts; the total has 5 equal-sized parts.','foundations'],['Rate','A ratio comparing quantities, often with different units.','12 meters per second compares distance with time.','foundations'],['Percent (%)','Per hundred.','15% = 15/100 = 0.15.','foundations'],['Exponent','A notation that describes a power. Whole-number exponents represent repeated multiplication.','2³ = 2 × 2 × 2 = 8. Other exponent types extend the pattern.','algebra'],['Reciprocal','The number that gives 1 when multiplied by a given nonzero number.','The reciprocal of 3/4 is 4/3. Zero has no reciprocal.','foundations'],['Square root (√)','The nonnegative number whose square is the given nonnegative number.','√9 = 3, while the equation x² = 9 has solutions ±3.','algebra'],['Absolute value (|x|)','Distance from zero on the real number line.','|−7| = 7. A distance cannot be negative.','algebra'],['Function','A rule assigning each allowed input exactly one output.','f(x) = x² sends both 2 and −2 to 4; that is still a function.','functions'],['Domain','The set of allowed inputs of a function or expression.','For 1/(x − 3), x = 3 is excluded.','functions'],['Range','The set of outputs actually produced.','For f(x) = x² with real inputs, the range is y ≥ 0.','functions'],['Slope','Change in vertical coordinate divided by the corresponding change in horizontal coordinate.','A slope of 2 means y increases by 2 when x increases by 1.','functions'],['Intercept','A point where a graph meets a coordinate axis.','In y = 2x + 3, the y-intercept is (0, 3).','functions'],['Inverse function','A function that reverses another function on an appropriate domain.','If f(x) = 2x + 1, its inverse is (x − 1)/2. It is not 1/f(x).','functions'],['Logarithm','The exponent needed to produce a number from a specified base.','log₂(8) = 3 because 2³ = 8.','functions'],['Radian','An angle measure defined by arc length divided by radius.','One full turn is 2π radians; a half turn is π radians.','geometry'],['Vector','A quantity with magnitude and direction, represented by components in a coordinate system.','A 10 N force to the right differs from a 10 N force upward.','engineering'],['Model','A simplified mathematical description of a situation.','d = vt models distance at constant speed. Its assumption matters.','engineering'],['Dimension','The type of physical quantity, such as length, time, or mass.','Meters and feet are both units of length; seconds measure time.','engineering'],['Approximation (≈)','A value or relationship close enough for a stated purpose, rather than exactly equal.','π ≈ 3.14. Keep track of how much precision the task needs.','engineering'],['Constraint','A condition that a solution must satisfy.','A physical length may need to be positive even when an equation also has a negative root.','engineering'],['Proof','A logical argument establishing a claim from definitions and accepted results.','Testing several examples can suggest a pattern; it does not prove every case.','reasoning']
].map(([title,meaning,example,group])=>({title,meaning,example,group}));
export function glossaryPage(){return `${pageIntro('THE LANGUAGE DESK','Make the symbols<br> <em>say something.</em>','A compact reference for words and symbols that appear throughout the path. The meaning of a symbol comes from its definition and context.')}<div class="filters"><label class="search-field" for="glossary-search">FIND A WORD OR SYMBOL<input id="glossary-search" type="search" placeholder="Try function, fraction, or =…"></label></div><div class="glossary-list" id="glossary-list">${glossaryRows(glossary)}</div><div class="inline-sources section">Definitions are original summaries of standard introductory mathematics. Reference: ${link('https://openstax.org/books/elementary-algebra-2e/pages/1-key-terms','Elementary Algebra chapter 1 key terms')} and ${link('https://openstax.org/books/precalculus-2e/pages/1-key-terms','Precalculus chapter 1 key terms')}.</div>`;}
function glossaryRows(items){return items.map(x=>`<article><h3>${esc(x.title)}</h3><div><p>${esc(x.meaning)}</p><small>${esc(x.example)}</small></div></article>`).join('')||'<p class="empty">No matching terms. Try a shorter search.</p>';}
export function mountGlossary(root){root.querySelector('#glossary-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();root.querySelector('#glossary-list').innerHTML=glossaryRows(glossary.filter(x=>(x.title+' '+x.meaning+' '+x.example).toLowerCase().includes(q)));});}

export function notebookPage(state,topic=''){topic=concepts.find(c=>c.id===topic)?.title||missions.find(m=>m.id===topic)?.title||topic;const saved=resources.filter(r=>state.saved.includes(r.id));return `${pageIntro('YOUR WORKSPACE','Keep what helps.<br> <em>Return to what matters.</em>','Collect a small shelf, record a mathematical idea in your own words, and keep track of the errors you have repaired. Everything here stays in this browser unless you export it.')}<div class="workspace-stats"><div><b>${saved.length}</b><span>saved resources</span></div><div><b>${Object.values(state.checks||{}).filter(Boolean).length}</b><span>self-checks marked</span></div><div><b>${(state.notes||[]).length}</b><span>personal notes</span></div></div><div class="notebook-layout"><article class="essay"><div class="eyebrow">WRITE TO UNDERSTAND</div><h2>Leave yourself a useful note.</h2><form id="note-form" class="note-form"><label for="note-title">Idea or question<input id="note-title" maxlength="120" required placeholder="Why can I multiply both sides?" value="${esc(topic)}"></label><label for="note-type">Type<select id="note-type"><option value="reflection">An idea in my own words</option><option value="error">A mistake and its repair</option><option value="question">A question to revisit</option></select></label><label for="note-text">Your explanation<textarea id="note-text" rows="6" maxlength="5000" required placeholder="The step I tried… Why it works or fails… A new example…"></textarea></label><button type="submit" class="btn primary">Save this note +</button><p class="smallprint">Notes are browser-local. Export a backup if you want to keep them elsewhere.</p></form></article><aside class="notebook-shelf"><div class="eyebrow">YOUR SMALL SHELF</div><h3>${saved.length?'Resources worth returning to.':'Keep the essentials close.'}</h3>${saved.length?saved.map(r=>`<div>${link(r.url,r.title)}<small>${r.role}</small></div>`).join(''):'<p>Use the star on a resource in the library to save it here.</p>'}<a class="btn" href="#library">Browse the library →</a><div class="note"><b>For a question you cannot yet answer</b><p>Write what you do know and the exact step that loses you. A specific question is much easier to bring to a teacher or tutor.</p></div></aside></div><section class="section"><div class="section-head"><h2>Your notes & questions.</h2><button class="btn" id="export-workspace">Export a backup ↓</button></div><div id="notes-list">${noteRows(state.notes||[])}</div><div id="delete-note-confirm" role="status"></div></section>`;}
function noteRows(notes){return notes.length?[...notes].reverse().map(n=>`<article class="saved-note"><div><span class="overline">${esc(n.type)} · ${esc(n.date.slice(0,10))}</span><h3>${esc(n.title)}</h3><p>${esc(n.text).replace(/\n/g,'<br> ')}</p></div><button class="btn small" data-delete-note="${esc(n.id)}" aria-label="Delete note ${esc(n.title)}">Remove</button></article>`).join(''):'<div class="empty"><h3>A good note can be three sentences.</h3><p>What the idea means. Why the step is valid. One example you can explain without help.</p></div>';}
export function mountNotebook(root,state,onSave,onToast){root.querySelector('#note-form').addEventListener('submit',e=>{e.preventDefault();const title=root.querySelector('#note-title').value.trim(),text=root.querySelector('#note-text').value.trim(),type=root.querySelector('#note-type').value;if(!title||!text)return;state.notes??=[];if(state.notes.length>=2000){onToast('The notebook has reached its 2,000-note limit. Export a backup before removing older notes.');return;}state.notes.push({id:'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),title:title.slice(0,120),text:text.slice(0,5000),type,date:new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())});onSave();root.querySelector('#notes-list').innerHTML=noteRows(state.notes);root.querySelector('#note-title').value='';root.querySelector('#note-text').value='';root.querySelector('.workspace-stats>div:last-child b').textContent=state.notes.length;onToast('Note saved in this browser.');});root.querySelector('#notes-list').addEventListener('click',e=>{const btn=e.target.closest('[data-delete-note]');if(!btn)return;const id=btn.dataset.deleteNote;const box=root.querySelector('#delete-note-confirm');box.innerHTML='<div class="note warn">Remove this note? This cannot be undone here. <button class="btn small" id="confirm-note-delete">Remove note</button> <button class="btn small" id="cancel-note-delete">Keep it</button></div>';box.querySelector('#cancel-note-delete').onclick=()=>box.replaceChildren();box.querySelector('#confirm-note-delete').onclick=()=>{state.notes=state.notes.filter(n=>n.id!==id);onSave();root.querySelector('#notes-list').innerHTML=noteRows(state.notes);root.querySelector('.workspace-stats>div:last-child b').textContent=state.notes.length;box.replaceChildren();onToast('Note removed.');};box.scrollIntoView({behavior:'smooth',block:'nearest'});});root.querySelector('#export-workspace').addEventListener('click',()=>exportWorkspace(state));}
export function exportWorkspace(state){downloadBackup(state);}

export function expansionSources(){const sourceItems=[...historyEntries.flatMap(h=>h.sources),...concepts.map(c=>c.source),...missions.map(m=>m.source)];const unique=[...new Map(sourceItems.map(s=>[s.url,s])).values()];return `<section class="section"><div class="section-head"><h2>The expanded reading trail.</h2><p>Direct sources for the history, concepts, and engineering examples. Each article also links its own supporting material.</p></div><div class="expanded-sources">${unique.map(s=>`<div>${link(s.url,s.title)}</div>`).join('')}</div><div class="note section"><b>About the diagnostic</b><p>The 12- or 24-question check is an original, informal guide to what to study next. It distinguishes wrong answers from skipped and not-yet-learned topics, and does not provide official college placement, a percentile, or a validated mastery claim.</p></div></section>`;}
